def point_type(name, fields, srid_map):
    class PointSubclass(Point):
        def __init__(self, *args, **kwargs):
            super().__init__(*args, **kwargs)
            self.name = name
            self.fields = fields
            self.srid_map = srid_map

        def __str__(self):
            return f"{self.name}({', '.join(str(field) for field in self.fields)})"

        def __repr__(self):
            return f"{self.name}({', '.join(repr(field) for field in self.fields)})"

        def __eq__(self, other):
            return (
                isinstance(other, PointSubclass)
                and self.name == other.name
                and self.fields == other.fields
                and self.srid_map == other.srid_map
            )

        def __ne__(self, other):
            return not self.__eq__(other)

        def __hash__(self):
            return hash((self.name, self.fields, self.srid_map))

    return PointSubclass

