def cached(cache, key=hashkey, lock=None):
    def decorator(func):
        def wrapper(*args, **kwargs):
            if lock is not None:
                with lock:
                    if key(*args, **kwargs) in cache:
                        return cache[key(*args, **kwargs)]
                    else:
                        result = func(*args, **kwargs)
                        cache[key(*args, **kwargs)] = result
                        return result
            else:
                if key(*args, **kwargs) in cache:
                    return cache[key(*args, **kwargs)]
                else:
                    result = func(*args, **kwargs)
                    cache[key(*args, **kwargs)] = result
                    return result
        return wrapper
    return decorator

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    def wrapper(func):
        cache = {}
        def _wrapper(*args, **kwargs):
            now = timer()
            for key, (value, timestamp) in list(cache.items()):
                if now - timestamp > ttl:
                    del cache[key]
            try:
                return cache[args]
            except KeyError:
                value = func(*args, **kwargs)
                cache[args] = (value, now)
                return value
        return _wrapper
    return wrapper

def mru_cache(maxsize=128, typed=False):
    def wrapper(func):
        cache = {}
        def wrapped(*args, **kwargs):
            key = (args, tuple(kwargs.items()))
            if key in cache:
                return cache[key]
            result = func(*args, **kwargs)
            cache[key] = result
            if len(cache) > maxsize:
                cache.popitem(last=False)
            return result
        return wrapped
    return wrapper

def lru_cache(maxsize=128, typed=False):
    def wrapper(func):
        cache = {}
        def wrapped(*args, **kwargs):
            if typed:
                key = (args, tuple(kwargs.items()))
            else:
                key = (args, tuple(kwargs.values()))
            if key in cache:
                return cache[key]
            result = func(*args, **kwargs)
            cache[key] = result
            if len(cache) > maxsize:
                cache.popitem(last=False)
            return result
        return wrapped
    return wrapper

