def lfu_cache(maxsize=128, typed=False):
    def wrapper(func):
        cache = {}
        use_count = {}
        def wrapped(*args, **kwargs):
            if typed:
                key = args[0]
            else:
                key = make_key(args, kwargs)
            if key in cache:
                use_count[key] += 1
                return cache[key]
            result = func(*args, **kwargs)
            cache[key] = result
            use_count[key] = 1
            while len(cache) > maxsize:
                min_key = min(use_count, key=use_count.get)
                del cache[min_key]
                del use_count[min_key]
            return result
        return wrapped
    return wrapper
