def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Get the list of resources in the application manifest
    resources = app.spec.manifest.resources

    # Iterate over the resources and generate a default observer schema for each one
    for resource in resources:
        # Get the resource type and name
        resource_type = resource.type
        resource_name = resource.name

        # Generate the default observer schema for this resource
        observer_schema = {
            "type": "object",
            "properties": {
                "status": {
                    "type": "object",
                    "properties": {
                        "observedGeneration": {
                            "type": "integer"
                        },
                        "conditions": {
                            "type": "array",
                            "items": {
                                "type": "object",
                                "properties": {
                                    "type": {
                                        "type": "string"
                                    },
                                    "status": {
                                        "type": "string"
                                    },
                                    "lastTransitionTime": {
                                        "type": "string",
                                        "format": "date-time"
                                    },
                                    "reason": {
                                        "type": "string"
                                    },
                                    "message": {
                                        "type": "string"
                                    }
                                },
                                "required": [
                                    "type",
                                    "status",
                                    "lastTransitionTime",
                                    "reason",
                                    "message"
                                ]
                            }
                        }
                    },
                    "required": [
                        "observedGeneration",
                        "conditions"
                    ]
                }
            },
            "required": [
                "status"
            ]
        }

        # Add the default observer schema to the resource
        resource.observer_schema = observer_schema

    # Return the updated application
    return app

