def validate_as_prior_version(self, prior):
    if not isinstance(prior, InventoryValidator):
        raise TypeError("prior must be an InventoryValidator object")
    if not self.is_consistent():
        raise ValueError("self inventory is not consistent")
    if not prior.is_consistent():
        raise ValueError("prior inventory is not consistent")
    if self.get_version() <= prior.get_version():
        raise ValueError("prior inventory version must be greater than self inventory version")
    if self.get_id() != prior.get_id():
        raise ValueError("self and prior inventory IDs must match")
    if self.get_timestamp() <= prior.get_timestamp():
        raise ValueError("self inventory timestamp must be greater than prior inventory timestamp")
    return True

