def extract_number_and_supplment_from_issue_element(issue):
    issue = issue.lower()
    number = ""
    supplement = ""
    for char in issue:
        if char.isdigit():
            number += char
        elif char == "s" or char == "S":
            supplement += char
        elif char == "p" or char == "P":
            supplement += char
        elif char == "r" or char == "R":
            supplement += char
        elif char == "." or char == "-":
            continue
        else:
            break
    return number, supplement
