def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    num_objects = 0
    good_objects = 0
    for root, dirs, files in os.walk(self.storage_root):
        for file in files:
            num_objects += 1
            file_path = os.path.join(root, file)
            if validate_objects and not self.is_valid_object(file_path):
                if show_warnings:
                    print(f"Warning: {file_path} is not a valid object")
                continue
            if check_digests and not self.is_valid_digest(file_path):
                if show_warnings:
                    print(f"Warning: {file_path} has an invalid digest")
                continue
            good_objects += 1
    return num_objects, good_objects

