def deep_merge_nodes(nodes):
    result = {}
    for node in nodes:
        key, value = node
        if key in result:
            if isinstance(value, ruamel.yaml.nodes.MappingNode):
                result[key] = deep_merge_nodes([(k, v) for k, v in value.value])
