def split(s, platform='this'):
    """
    Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        platform = os.name

    if platform == 'posix':
        return _split_posix(s)
    elif platform == 'nt':
        return _split_nt(s)
    else:
        raise ValueError("invalid platform specified")

def _split_posix(s):
    # Split the string using shell-like syntax
    result = []
    i = 0
    while i < len(s):
        c = s[i]
        if c.isspace():
            i += 1
            continue
        if c == "'" or c == '"':
            # Handle quoted string
            j = i + 1
            while j < len(s) and s[j] != c:
                j += 1
            if j >= len(s):
                raise ValueError("unmatched quote in command line")
            result.append(s[i+1:j].replace("\\" + c, c))
            i = j + 1
        else:
            # Handle non-quoted string
            j = i + 1
            while j < len(s) and not s[j].isspace():
                j += 1
            result.append(s[i:j])
            i = j

    return result

def _split_nt(s):
    # Split the string using Windows command line syntax
    result = []
    i = 0
    while i < len(s):
        c = s[i]
        if c.isspace():
            i += 1
            continue
        if c == '"':
            # Handle quoted string
            j = i + 1
            while j < len(s) and s[j] != '"':
                j += 1
            if j >= len(s):
                raise ValueError("unmatched quote in command line")
            result.append(s[i+1:j].replace('\\"', '"'))
            i = j + 1
        else:
            # Handle non-quoted string
            j = i + 1
            while j < len(s) and not s[j].isspace():
                j += 1
            result.append(s[i:j])
            i = j

    return result
